const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.header nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
nav.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')});
const motion=document.querySelector('.motion-toggle');
motion.addEventListener('click',()=>{const paused=document.body.classList.toggle('motion-paused');motion.setAttribute('aria-pressed',paused);motion.setAttribute('aria-label',paused?'Resume motion':'Pause motion');motion.querySelector('.motion-label').textContent=paused?'Motion off':'Motion on';window.dispatchEvent(new Event('motionchange'))});
addEventListener('scroll',()=>{const h=document.documentElement;document.querySelector('.scroll-progress').style.width=`${scrollY/Math.max(1,h.scrollHeight-innerHeight)*100}%`},{passive:true});
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
if(reduce.matches){document.body.classList.add('motion-paused');motion.setAttribute('aria-pressed','true');motion.setAttribute('aria-label','Resume motion');motion.querySelector('.motion-label').textContent='Motion off';}
let sceneModule,revealObserver,routeController,activeTransition,sceneGate,sceneLoading;
function prepareScenes(){sceneGate?.disconnect();if(sceneModule){sceneModule.mountScenes();return;}if(sceneLoading)return;sceneGate=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){sceneGate.disconnect();sceneLoading=import('./scene.js').then(m=>sceneModule=m).catch(()=>document.body.classList.add('static-rendering'));}},{rootMargin:'400px'});document.querySelectorAll('[data-scene]').forEach(el=>sceneGate.observe(el));}
function enhance(){
  prepareScenes();
  revealObserver?.disconnect();
  revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target);}}),{threshold:.08});
  document.body.classList.add('js-reveal');document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
  document.querySelectorAll('.product-card').forEach(el=>{const light=document.createElement('div');light.className='scene-cursor-light';el.querySelector('.scene').append(light);el.addEventListener('pointermove',e=>{if(reduce.matches||document.body.classList.contains('motion-paused')||e.pointerType!=='mouse')return;const b=el.getBoundingClientRect();light.style.setProperty('--mx',`${(e.clientX-b.left)/b.width*100}%`);light.style.setProperty('--my',`${(e.clientY-b.top)/b.height*100}%`);el.style.transform=`perspective(1600px) rotateX(${(.5-(e.clientY-b.top)/b.height)*1.6}deg) rotateY(${((e.clientX-b.left)/b.width-.5)*2}deg)`;},{passive:true});el.addEventListener('pointerleave',()=>el.style.transform='');});
  document.querySelectorAll('.magnetic').forEach(el=>{el.addEventListener('pointermove',e=>{if(reduce.matches||e.pointerType!=='mouse'||document.body.classList.contains('motion-paused'))return;const b=el.getBoundingClientRect();el.style.transform=`translate(${(e.clientX-b.left-b.width/2)*.08}px,${(e.clientY-b.top-b.height/2)*.08}px)`;},{passive:true});el.addEventListener('pointerleave',()=>el.style.transform='');});
  document.querySelectorAll('.gallery-item').forEach(el=>el.addEventListener('click',()=>{const dialog=document.createElement('dialog');dialog.className='lightbox';dialog.setAttribute('aria-label',el.getAttribute('aria-label'));const img=document.createElement('img');img.src=el.dataset.image;img.alt=el.querySelector('img').alt;const close=document.createElement('button');close.textContent='Close image ×';dialog.append(img,close);document.body.append(dialog);dialog.showModal();close.focus();close.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});dialog.addEventListener('close',()=>{dialog.remove();el.focus();});}));
}
enhance();
async function route(url,trigger,pop=false){
  activeTransition?.skipTransition();routeController?.abort();routeController=new AbortController();
  try{const response=await fetch(url.pathname,{signal:routeController.signal});if(!response.ok)throw Error('route');const text=await response.text();const doc=new DOMParser().parseFromString(text,'text/html');const main=doc.querySelector('main');if(!main)throw Error('main');
    const scene=trigger?.querySelector('.scene')||document.querySelector('.detail-stage');if(scene)scene.style.viewTransitionName='product-stage';const incoming=main.querySelector('.detail-stage');if(incoming)incoming.style.viewTransitionName='product-stage';
    const change=()=>{document.querySelector('main').replaceWith(main);document.title=doc.title;for(const selector of ['meta[name="description"]','link[rel="canonical"]','meta[property="og:title"]','meta[property="og:description"]','meta[property="og:url"]','meta[name="twitter:title"]','meta[name="twitter:description"]','script[type="application/ld+json"]']){const fresh=doc.querySelector(selector),old=document.querySelector(selector);if(fresh&&old)old.replaceWith(fresh);}if(!pop)history.pushState(null,'',url.pathname+url.hash);enhance();const target=url.hash?document.querySelector(url.hash):null;window.scrollTo({top:target?target.getBoundingClientRect().top+scrollY-95:0,behavior:'instant'});const heading=document.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}document.querySelector('.route-announcement').textContent=doc.title;};
    if(document.startViewTransition&&!reduce.matches&&!document.body.classList.contains('motion-paused')){main.setAttribute('aria-busy','true');activeTransition=document.startViewTransition(change);await activeTransition.finished.catch(()=>{});main.removeAttribute('aria-busy');}else{change();}if(incoming)incoming.style.viewTransitionName='none';
  }catch(error){if(error.name!=='AbortError')location.href=url.href;}
}
document.addEventListener('click',e=>{const link=e.target.closest('a');if(!link||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||link.target||link.hasAttribute('download'))return;const url=new URL(link.href);if(url.origin!==location.origin||url.pathname===location.pathname)return;if(url.pathname==='/'||url.pathname.startsWith('/products/')){e.preventDefault();route(url,link);}});
addEventListener('popstate',()=>route(new URL(location.href),null,true));
if(!sessionStorage.getItem('sky-seen')&&!reduce.matches){const loader=document.createElement('div');loader.className='loading-screen';loader.setAttribute('aria-hidden','true');loader.innerHTML='<img src="/assets/skyexch247.png" alt=""><div class="loading-line"></div><span>ENTER THE COLLECTION</span>';document.body.append(loader);const finish=()=>{loader.classList.add('done');setTimeout(()=>loader.remove(),500);sessionStorage.setItem('sky-seen','1');};Promise.race([document.fonts.ready,new Promise(r=>setTimeout(r,800))]).then(finish);}

